window.products.push({"id":960685,"name":"Fishermen Welcome Personalized Lake House Sign","category":"homeandappliances","retail price":89.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/81SDCTv646L._AC_SL1246_.jpg","description":"Our Fishermen Personalized Lake Sign is created from an original wood carving by artist Al Pisano. We carve your personalization into the sign and then each piece is hand painted and stained to capture all the detail and depth of the original wood carving. This sign measures 12 1/2 inches by 10 1/2 inch and about 1 inch thick. There is a recessed hanger in the back and you can hang this sign indoors or outdoors. Made in USA.","images":["https://m.media-amazon.com/images/I/81SDCTv646L._AC_SL1246_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Piazza Pisano","source_asin":"B074PHF9JM","category_path":"Home & Kitchen"},"sku":"BM-960685","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B074PHF9JM","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B074PHF9JM","price_pending":true,"merchant_ready":false});
